  elapsed = null;
}
clickAt(1500);
console.log(elapsed);
signal(2000);
clickAt(2200);
reset();
console.log(startedAt, elapsed);
```
Output:
```text
null
null null
```
The early click is ignored. Later, `reset()` clears both the start time and the result.
